export function openSketch(onClose){let lines=[],backup=null,current=null;try{lines=JSON.parse(localStorage.getItem('yasmin-sketch-v1')||'[]');if(!Array.isArray(lines))lines=[]}catch{}let root=document.createElement('section');root.id='sketch';root.innerHTML='<div class="sketchHead"><div><small>UM CANTINHO SEM PRESSA</small><h2>Só um rabisco, se quiser.</h2></div><button id="closeSketch">Voltar</button></div><p>Não precisa ficar bonito, nem virar presente. Este espaço é seu.</p><canvas aria-label="Papel para desenhar com o dedo"></canvas><div class="sketchTools"><div id="colors"></div><button id="undoSketch">Desfazer</button><button id="clearSketch">Limpar</button><button id="saveSketch">Salvar imagem</button></div><small>O rascunho fica neste aparelho. Nada é enviado automaticamente.</small>';document.body.append(root);let canvas=root.querySelector('canvas');canvas.width=1000;canvas.height=700;let ctx=canvas.getContext('2d'),color='#4e5263';
function draw(){ctx.fillStyle='#faf3e5';ctx.fillRect(0,0,1000,700);for(let l of lines){if(!Array.isArray(l.points)||l.points.length===0)continue;ctx.strokeStyle=l.color||'#4e5263';ctx.fillStyle=ctx.strokeStyle;ctx.lineWidth=5;ctx.lineCap=ctx.lineJoin='round';ctx.beginPath();l.points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();if(l.points.length===1){ctx.beginPath();ctx.arc(l.points[0].x,l.points[0].y,2.5,0,Math.PI*2);ctx.fill()}}}
function store(){try{localStorage.setItem('yasmin-sketch-v1',JSON.stringify(lines))}catch{}}
function point(e){let r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*1000/r.width,y:(e.clientY-r.top)*700/r.height}}
canvas.onpointerdown=e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);current={color,points:[point(e)]};lines.push(current);if(lines.length>150)lines.shift();draw()};canvas.onpointermove=e=>{if(!current)return;e.preventDefault();if(current.points.length<3000)current.points.push(point(e));draw()};for(let ev of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,()=>{current=null;store()});
for(let c of ['#4e5263','#a76b7b','#d69a65','#d7bd6a','#729b81','#6e97b1','#9782b0']){let b=document.createElement('button');b.style.background=c;b.setAttribute('aria-label','Cor '+c);b.onclick=()=>{color=c;root.querySelectorAll('#colors button').forEach(x=>x.style.outline='');b.style.outline='3px solid #d2bc91'};root.querySelector('#colors').append(b)}
root.querySelector('#undoSketch').onclick=()=>{if(backup){lines=backup;backup=null}else lines.pop();draw();store()};root.querySelector('#clearSketch').onclick=()=>{backup=lines;lines=[];draw();store()};root.querySelector('#saveSketch').onclick=()=>{draw();let a=document.createElement('a');a.download='meu-rabisco.png';a.href=canvas.toDataURL('image/png');a.click()};root.querySelector('#closeSketch').onclick=()=>{store();root.remove();onClose()};draw()}
